SELECT sessions.device, COUNT(web_events.id) web_event_count, SUM(CASE WHEN web_events.event_type = 'purchase' THEN web_events.duration_sec ELSE 0 END) purchase_duration_sec, MAX(web_events.duration_sec) - MIN(web_events.duration_sec) duration_sec_range FROM sessions LEFT JOIN web_events ON web_events.session_id = sessions.id WHERE sessions.browser IS NOT NULL GROUP BY sessions.device HAVING MAX(web_events.duration_sec) - MIN(web_events.duration_sec) >= 53 ORDER BY web_event_count DESC
